"options_hash":"v1:e1485745f5dddca69e5c24ddd28846c3bad4340850abc55b0774aa1ef13861b9"},{"exercise_id":"it-a1-u12-l05-e01","item_id":"it-a1-u12-l05-e01","options_hash":"v1:c5b8f09bacf53ac53caccf39402ffacc7f2182e7812db74b980859be9c0f30a9"},{"exercise_id":"it-a1-u12-l05-e02","item_id":"it-a1-u12-l05-e02","options_hash":"v1:eb036e1c0866fd321ab4109323d088f85f882612bb5964ae9cbc049fa0c8b94c"},{"exercise_id":"it-a1-u12-l05-e03","item_id":"it-a1-u12-l05-e03","options_hash":"v1:b4d5178459a96f58925fe5ac71b8a5552f9dcc8b6edeb1d9d901e44c97ae13fa"},{"exercise_id":"it-a1-u12-l05-e04","item_id":"it-a1-u12-l05-e04","options_hash":"v1:6c959caef2ca3a494db262218617cd476f7f693132333d923abd6236a27321b4"},{"exercise_id":"it-a1-u12-l05-e05","item_id":"it-a1-u12-l05-e05","options_hash":"v1:e051a4dd3c751ba9b30535ed56dc25d3c140ed0be08b93716f9fec578d96ca9a"},{"exercise_id":"it-a1-u12-listen-e01","item_id":"it.gen.listen_choice.it-cosa","options_hash":"v1:04cbf49d36578073e7be32a771e8d858bb4c4a09edf317b2aa553372a9dc3e6d"},{"exercise_id":"it-a1-u12-listen-e02","item_id":"it.gen.listen_choice.it-perche","options_hash":"v1:8caa93a1c3bd25820088b51c728bb6877e4b6a03fd1f1ded33f1363eb479e821"},{"exercise_id":"it-a1-u12-listen-e03","item_id":"it-a1-u12-l01-e03","options_hash":"v1:b7e32d61f531f554eb5b1919e135dad3c4e66e683e10cff87e4db3af8c957d74"},{"exercise_id":"it-a1-u12-listen-e04","item_id":"it-a1-u12-l03-e03","options_hash":"v1:149a902736acd22d5e30c499034b717a80194f2f713c51353948be96fdbddf16"},{"exercise_id":"it-a1-u12-listen-e05","item_id":"it.gen.listen_choice.it-scarpe","options_hash":"v1:34504dc4cac1f8ec3d763ec2a8b4a00d55efc44f5e4cfe7ec48e2e440fee45f7"},{"exercise_id":"it-a1-u12-listen-e06","item_id":"it-a1-u12-l04-e05","options_hash":"v1:60561fcbd556cc07447cbc84d49d4f70dcf57d39b4edf5ff732c3b1315a464b5"},{"exercise_id":"it-a1-u12-listen-e07","item_id":"it.gen.listen_choice.it-quando","options_hash":"v1:408b02fc4cb8104831bcafa4e0e4990a95fd8cc92fd4f0b8eeac9deb6c70ebe8"},{"exercise_id":"it-a1-u12-listen-e08","item_id":"it.gen.listen_choice.it-economico","options_hash":"v1:da69ee9b61f52c5382bb8c0f5412bc415cd2c373c863cb2b060c8d618195ade2"},{"exercise_id":"it-a1-u12-listen-e09","item_id":"it.gen.listen_choice.it-cosa-fai","options_hash":"v1:0a56a48efe10f8ecef360a165a156998199d92b51d5365524acd44af4ffa7029"},{"exercise_id":"it-a1-u12-listen-e10","item_id":"it.gen.listen_choice.it-euro","options_hash":"v1:ea89d330bb6f29f00d28b20c33d708383aed9d943865e45919cc69ded5a0c450"},{"exercise_id":"it-a1-u12-words-e01","item_id":"it.gen.translation_choice.it-chi","options_hash":"v1:0b528756dbe119de87e7b1ec7ded0f2c4c4ed25b7b2dc3accd3a95e770401c3d"},{"exercise_id":"it-a1-u12-words-e07","item_id":"it.gen.translation_choice.it-quale","options_hash":"v1:f82c406d09c3612d8f03b6521122304efbf6adf0132deedc89d0823d39075c5f"},{"exercise_id":"it-a1-u12-words-e08","item_id":"it.gen.translation_choice.it-cosa","options_hash":"v1:107ee0ecc5ee5fcc8d20af1dc71cf7399f49ffb54334cb818dd778a41fd67036"},{"exercise_id":"it-a1-u12-final-e02","item_id":"it.gen.translation_choice.it-biglietto","options_hash":"v1:0b171120e7697db8e5221961983ce690bf069e29d83c4ee51623c036f6fa753f"},{"exercise_id":"it-a1-u12-final-e08","item_id":"it.gen.listen_choice.it-cosa-fai","options_hash":"v1:5b3e9d4f502e43be3e5d3fcdd6d0a4ec96ce627c822ae1f708095f910328087d"},{"exercise_id":"it-a1-u12-final-e10","item_id":"it-a1-u12-l02-e04","options_hash":"v1:b661555bbe923cc287347c3e43b0fe09213e7fc6a3e5ac93bd86274e454facab"}]}}$content$::jsonb;
begin

-- Conjuntos de opciones (content/option-sets.ts).
declare
  v_bad text;
begin

select string_agg(item_id || '@' || options_hash, ', ') into v_bad from (
  select x.item_id, x.options_hash
  from jsonb_to_recordset(d -> 'catalog' -> 'option_sets')
    as x(item_id text, version_hash text, options_hash text)
  left join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.version_hash
  where v.id is null
  order by 1, 2 limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: conjuntos de una versión que no existe: %', v_bad;
end if;

select string_agg(item_id || '@' || options_hash, ', ') into v_bad from (
  select x.item_id, x.options_hash
  from jsonb_to_recordset(d -> 'catalog' -> 'option_sets')
    as x(item_id text, version_hash text, options_hash text, format text, options jsonb, answer_index smallint)
  join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.version_hash
  join public.exercise_option_sets s on s.item_version_id = v.id and s.options_hash = x.options_hash
  where (s.format, s.options, s.answer_index) is distinct from (x.format, x.options, x.answer_index)
  order by 1, 2 limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: conjuntos ya cargados con el mismo hash y otras opciones: %', v_bad;
end if;

insert into public.exercise_option_sets (item_id, item_version_id, options_hash, format, options, answer_index,
  origin, generator, generator_version)
select x.item_id, v.id, x.options_hash, x.format, x.options, x.answer_index, x.origin, x.generator,
  x.generator_version
from jsonb_array_elements(d -> 'catalog' -> 'option_sets') with ordinality as t(j, ord),
  jsonb_to_record(t.j)
    as x(item_id text, version_hash text, options_hash text, format text, options jsonb, answer_index smallint,
         origin text, generator text, generator_version text)
join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.version_hash
where not exists (select 1 from public.exercise_option_sets s
                  where s.item_version_id = v.id and s.options_hash = x.options_hash)
order by t.ord;

end;

-- Conjunto vigente de cada ubicación de elección (content/option-sets.ts).
declare
  v_bad text;
begin

select string_agg(exercise_id, ', ') into v_bad from (
  select x.exercise_id
  from jsonb_to_recordset(d -> 'catalog' -> 'placement_option_sets')
    as x(exercise_id text, item_id text, options_hash text)
  left join public.exercises e on e.id = x.exercise_id
  left join public.exercise_option_sets s
    on s.item_version_id = e.item_version_id and s.options_hash = x.options_hash
  where e.id is null or e.item_id is distinct from x.item_id or s.id is null
  order by 1 limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: ubicaciones sin fila, de otro ítem o sin ese conjunto en su versión: %', v_bad;
end if;

update public.exercises e set option_set_id = s.id
from jsonb_to_recordset(d -> 'catalog' -> 'placement_option_sets')
  as x(exercise_id text, item_id text, options_hash text)
join public.exercise_option_sets s on s.options_hash = x.options_hash
where e.id = x.exercise_id and s.item_version_id = e.item_version_id
  and e.option_set_id is distinct from s.id;

-- Checksum de la duplicación transitoria: exercises conserva la copia que lee la app.
select string_agg(id, ', ') into v_bad from (
  select e.id
  from public.exercises e
  join public.exercise_option_sets s on s.id = e.option_set_id
  where e.id in (select x ->> 'exercise_id' from jsonb_array_elements(d -> 'catalog' -> 'placement_option_sets') x)
    and ((select jsonb_agg(o -> 'text' order by n) from jsonb_array_elements(s.options) with ordinality as t(o, n))
           is distinct from e.payload -> 'options'
         or s.options -> s.answer_index::integer ->> 'text' is distinct from e.answer)
  order by e.id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: la copia de exercises no coincide con su conjunto: %', v_bad;
end if;

select string_agg(id, ', ') into v_bad from (
  select e.id
  from jsonb_to_recordset(d -> 'catalog' -> 'placement_versions') as x(exercise_id text)
  join public.exercises e on e.id = x.exercise_id
  where e.type in ('image_choice', 'translation_choice', 'fill_blank', 'listen_choice')
    and e.option_set_id is null
  order by e.id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: ubicaciones de elección con versión y sin conjunto: %', v_bad;
end if;

end;

end
$polygo_content$;
